// self-contained SVG that goes through the normal SVG import pipeline (parseSvgSource /
// sampleSvgSource), so gradients become per-particle colours and outlines stay crisp.
import type { SvgDistribution, SvgSamplingMode } from "../svgSource";

export interface LibraryShape {
  id: string;
  name: string;
  tag: string;
  markup: string;
  mode: SvgSamplingMode;
  distribution: SvgDistribution;
  /** Particle count that gives the shape its best detail. */
  count: number;
  /** Representative colours (used for the thumbnail glow). */
  swatch: string[];
}

export function shapeThumbnail(markup: string): string {
  return `data:image/svg+xml;utf8,${encodeURIComponent(markup)}`;
}

